INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Netzwerkkarte immer eine drahtlose Verbindung unterstützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Netzwerkkarte für ein IT-System auswähle?', 3, '[{"text": "Übertragungsrate", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Schnellste Installation", "correct": false, "because": "Leistung zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Netzwerkkarte?', 5, '[{"text": "MAC-Adresse", "correct": true, "because": "Eindeutige Kennung"}, {"text": "Datenübertragung", "correct": true, "because": "Verbindet Netzwerke"}, {"text": "Büromöbel", "correct": false, "because": "Kein Merkmal"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Netzwerkkarte hat eine MAC-Adresse. b) Sie ist immer drahtlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Netzwerkkarte für ein IT-System auswähle?', 4, '[{"text": "Übertragungsrate", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerkkarte immer eine drahtlose Verbindung benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Netzwerkkarte?', 3, '[{"text": "Netzwerkverbindung", "correct": true, "because": "Ermöglicht Kommunikation"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei einer Netzwerkkarte entscheidend?', 5, '[{"text": "Bandbreite", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Anschlusstyp", "correct": true, "because": "Definiert Verbindung"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine Netzwerkkarte unterstützt Ethernet. b) Sie ist immer für WLAN geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer WLAN"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Netzwerkkarte effektiv einzusetzen?', 4, '[{"text": "Treiber", "correct": false, "because": "Sichern Funktion"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Ermöglichen Kommunikation"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Netzwerkkarte immer für Hochgeschwindigkeitsnetzwerke geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Modell"}, {"text": "Ja", "correct": false, "because": "Nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Netzwerkkarte?', 4, '[{"text": "Zuverlässige Verbindung", "correct": true, "because": "Stabile Kommunikation"}, {"text": "Hohe Datenrate", "correct": true, "because": "Schnelle Übertragung"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Netzwerkkarte nur für kabelgebundene Netzwerke geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WLAN möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um eine Netzwerkkarte für ein System auszuwählen?', 3, '[{"text": "Übertragungsrate", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Günstigster Preis", "correct": false, "because": "Funktion wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Netzwerkkarte hat eine eindeutige MAC-Adresse. b) Sie unterstützt immer 10 Gbit/s.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Geschwindigkeit variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einer Netzwerkkarte?', 5, '[{"text": "Anschlusstyp", "correct": true, "because": "Definiert Verbindung"}, {"text": "Treiberunterstützung", "correct": true, "because": "Sichert Funktion"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich eine Netzwerkkarte auswähle?', 3, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Einsatz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Netzwerkkarte ohne Treiber funktionieren?', 3, '[{"text": "Nein", "correct": true, "because": "Treiber nötig"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Netzwerkkarte immer eine drahtlose Verbindung unterstützt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kabelgebunden"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für eine Netzwerkkarte?', 4, '[{"text": "MAC-Adresse", "correct": true, "because": "Eindeutige Kennung"}, {"text": "Schnellste Installation", "correct": false, "because": "Funktion zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
